flags.typeql:
match
$u isa user, has x_coordinate $x;
$x > 10000.0;
sort $x;
limit 3;
fetch {
  "handle": $u.handle,
  "x_coordinate": $x
};

match
$u isa user, has handle $h, has area $a, has size $s;
let $total = $a + $s;
sort $total desc;
limit 5;
fetch {
  "user": $h,
  "total": $total
};

match
$u isa user, has color "#3CB371";
limit 5;
fetch {
  "handle": $u.handle
};

match
$u1 isa user;
$rel isa interacted (source_user: $u1, target_user: $u2);
reduce $interactions = count($rel) groupby $u1;
match
$interactions > 1;
sort $interactions desc;
limit 5;
fetch {
  "user": $u1.handle,
  "interactions": $interactions
};

match
$u1 isa user, has handle "vtcodes.dev";
interacted (source_user: $u1, target_user: $u2);
$u2 has handle $h;
limit 5;
fetch {
  "interactedUser": $h
};

match
$u isa user, has y_coordinate $y;
$y < -5000.0;
sort $y;
limit 3;
fetch {
  "label": $u.handle,
  "y": $y
};
